//! Unique original required-list validation. Inputs/results are unsealed DATA;
//! an arbitrary iterator does not certify complete registered-policy coverage.
use crate::{scopes::Scopes,key_policy_control::{self as kc,Control}};
#[derive(Clone,Copy)]pub struct Requirement<'a>{pub name:&'a str,pub group:&'a str,pub lists:&'a[&'a str]}
fn row<C:Control>(c:&mut C,rows:&mut Vec<String>)->Result<(),C::Error>{if !C::CHECKED||rows.len()<rows.capacity(){return Ok(())}let target=rows.capacity().checked_mul(2).map(|n|n.max(4)).ok_or_else(||c.overflow())?;let bound=target.checked_mul(4).ok_or_else(||c.overflow())?;kc::reserve(c,||bound.checked_mul(std::mem::size_of::<String>())?.checked_add(128))?;rows.try_reserve_exact(target-rows.len()).map_err(|_|c.allocation_failed())?;if rows.capacity()>bound{return Err(c.allocation_failed())}Ok(())}
pub(crate) fn validate_one_using<C:Control>(meta:Requirement<'_>,scopes:&Scopes,c:&mut C,problems:&mut Vec<String>)->Result<(),C::Error>{c.checkpoint()?;let scope=scopes.borrowed_for_lint(meta.name,meta.group);for key in meta.lists{c.checkpoint()?;if !scope.is_some_and(|scope|scope.lists.contains_key(*key)){let message=kc::format(c,format_args!("lint_scopes.toml: [lint.{}.lists] is missing \x60{}\x60",meta.name,key))?;row(c,problems)?;problems.push(message);}}Ok(())}
pub fn validate_using<'a,C:Control>(requirements:impl IntoIterator<Item=Requirement<'a>>,scopes:&Scopes,c:&mut C)->Result<Vec<String>,C::Error>{let mut problems=Vec::new();for meta in requirements{validate_one_using(meta,scopes,c,&mut problems)?;}c.checkpoint()?;Ok(problems)}

#[cfg(test)]mod tests{use super::*;
 #[test]fn exact_name_precedes_group_and_missing_lists_preserve_registration_and_key_order(){let scopes=Scopes::parse("[lint.sys.lists]\nshared=[]\n[lint.\"sys/own\".lists]\nlocal=[]\n").unwrap();let rows=[Requirement{name:"sys/grouped",group:"sys",lists:&["shared","missing_first"]},Requirement{name:"sys/own",group:"sys",lists:&["shared","local","missing_second"]},Requirement{name:"last",group:"",lists:&["z","a"]}];let actual=validate_using(rows,&scopes,&mut kc::Compatibility).unwrap();assert_eq!(actual,["lint_scopes.toml: [lint.sys/grouped.lists] is missing `missing_first`","lint_scopes.toml: [lint.sys/own.lists] is missing `shared`","lint_scopes.toml: [lint.sys/own.lists] is missing `missing_second`","lint_scopes.toml: [lint.last.lists] is missing `z`","lint_scopes.toml: [lint.last.lists] is missing `a`"]);}
 struct Probe{left:usize,polls:usize,fail:usize}impl Control for Probe{type Error=std::io::Error;const CHECKED:bool=true;fn checkpoint(&mut self)->Result<(),Self::Error>{self.polls+=1;if self.polls==self.fail{Err(std::io::Error::from_raw_os_error(1450))}else{Ok(())}}fn reserve(&mut self,n:usize)->Result<(),Self::Error>{self.left=self.left.checked_sub(n).ok_or_else(||std::io::Error::from(std::io::ErrorKind::OutOfMemory))?;Ok(())}fn overflow(&mut self)->Self::Error{std::io::ErrorKind::OutOfMemory.into()}fn allocation_failed(&mut self)->Self::Error{std::io::ErrorKind::OutOfMemory.into()}}
 #[test]fn actual_control_denial_and_first_io_never_return_partial_problems(){let req=||[Requirement{name:"actual",group:"",lists:&["needed"]}];let scopes=Scopes::default();let mut denied=Probe{left:0,polls:0,fail:usize::MAX};assert_eq!(validate_using(req(),&scopes,&mut denied).unwrap_err().kind(),std::io::ErrorKind::OutOfMemory);let mut actual=Probe{left:4096,polls:0,fail:2};assert_eq!(validate_using(req(),&scopes,&mut actual).unwrap_err().raw_os_error(),Some(1450));let mut fresh=Probe{left:4096,polls:0,fail:usize::MAX};assert_eq!(validate_using(req(),&scopes,&mut fresh).unwrap().len(),1);}
}
